/**
  * UI implementation for STM32F469I-DISCO LCD
  */
#include "ui.h"
#include "stm32469i_discovery.h"
#include "stm32469i_discovery_lcd.h"
#include "stm32469i_discovery_sdram.h"
#include "logo_ptit.h"

static ui_screen_t current_screen = UI_SCREEN_MAIN;

static void UI_DrawLogo(uint16_t x0, uint16_t y0)
{
    uint32_t width = BSP_LCD_GetXSize();
    uint32_t *fb = (uint32_t *)LCD_FB_START_ADDRESS;

    for (uint32_t r = 0; r < LOGO_PTIT_HEIGHT; r++) {
        for (uint32_t c = 0; c < LOGO_PTIT_WIDTH; c++) {
            uint32_t color = logo_ptit_data[r * LOGO_PTIT_WIDTH + c];
            if ((color & 0xFF000000) != 0) {
                fb[(y0 + r) * width + (x0 + c)] = color;
            }
        }
    }
}

void UI_Init(void)
{
    BSP_SDRAM_Init();
    BSP_LCD_Init();
    BSP_LCD_LayerDefaultInit(0, LCD_FB_START_ADDRESS);
    BSP_LCD_SelectLayer(0);
    BSP_LCD_DisplayOn();
    UI_ShowMainScreen();
}

void UI_ShowMainScreen(void)
{
    current_screen = UI_SCREEN_MAIN;

    BSP_LCD_Clear(LCD_COLOR_WHITE);

    /* Logo PTIT */
    UI_DrawLogo(30, 120);

    /* Thong tin De tai & Hoc vien */
    BSP_LCD_SetBackColor(LCD_COLOR_WHITE);

    BSP_LCD_SetTextColor(LCD_COLOR_RED);
    BSP_LCD_SetFont(&Font16);
    BSP_LCD_DisplayStringAt(0, 30, (uint8_t *)"HOC VIEN CONG NGHE BUU CHINH VIEN THONG", CENTER_MODE);
    BSP_LCD_DisplayStringAt(0, 55, (uint8_t *)"KHOA KY THUAT DIEN TU 1", CENTER_MODE);

    BSP_LCD_SetTextColor(LCD_COLOR_DARKBLUE);
    BSP_LCD_SetFont(&Font20);
    BSP_LCD_DisplayStringAt(300, 130, (uint8_t *)"DO AN TOT NGHIEP", LEFT_MODE);
    BSP_LCD_DisplayStringAt(300, 160, (uint8_t *)"HE THONG TAC TU EIDE v3", LEFT_MODE);

    BSP_LCD_SetTextColor(LCD_COLOR_BLACK);
    BSP_LCD_SetFont(&Font16);
    BSP_LCD_DisplayStringAt(300, 210, (uint8_t *)"DT: Nghien cuu & Trien khai EIDE Agent", LEFT_MODE);
    BSP_LCD_DisplayStringAt(300, 240, (uint8_t *)"tren Bo STM32F469I-Discovery", LEFT_MODE);
    BSP_LCD_DisplayStringAt(300, 280, (uint8_t *)"Sinh vien : Nguyen Dinh Cong", LEFT_MODE);
    BSP_LCD_DisplayStringAt(300, 310, (uint8_t *)"GVHD      : Nhom Nghien Cuu He Thong Nhung", LEFT_MODE);

    /* Nut chuyen man hinh */
    BSP_LCD_SetTextColor(LCD_COLOR_BLUE);
    BSP_LCD_FillRect(280, 390, 480, 50);
    BSP_LCD_SetBackColor(LCD_COLOR_BLUE);
    BSP_LCD_SetTextColor(LCD_COLOR_WHITE);
    BSP_LCD_SetFont(&Font16);
    BSP_LCD_DisplayStringAt(0, 407, (uint8_t *)"[ AN NUT USER BUTTON (PA0) DE XEM CHI TIET ]", CENTER_MODE);
}

void UI_ShowDetailsScreen(void)
{
    current_screen = UI_SCREEN_DETAILS;

    BSP_LCD_Clear(LCD_COLOR_DARKBLUE);

    BSP_LCD_SetBackColor(LCD_COLOR_DARKBLUE);
    BSP_LCD_SetTextColor(LCD_COLOR_YELLOW);
    BSP_LCD_SetFont(&Font20);
    BSP_LCD_DisplayStringAt(0, 25, (uint8_t *)"=== TINH NANG HE THONG EIDE v3 ===", CENTER_MODE);

    BSP_LCD_SetTextColor(LCD_COLOR_WHITE);
    BSP_LCD_SetFont(&Font16);
    BSP_LCD_DisplayStringAt(50, 80,  (uint8_t *)"1. He dieu hanh FreeRTOS v10.x da tac vu:", LEFT_MODE);
    BSP_LCD_SetTextColor(LCD_COLOR_CYAN);
    BSP_LCD_DisplayStringAt(80, 110, (uint8_t *)"- Task 1: Blink 4 LEDs (PG6, PD4, PD5, PK3)", LEFT_MODE);
    BSP_LCD_DisplayStringAt(80, 135, (uint8_t *)"- Task 2: Giam sat nut bam User PA0 (Debounce)", LEFT_MODE);
    BSP_LCD_DisplayStringAt(80, 160, (uint8_t *)"- Task 3: Quan ly giao dien LCD & do hoa DSI", LEFT_MODE);

    BSP_LCD_SetTextColor(LCD_COLOR_WHITE);
    BSP_LCD_DisplayStringAt(50, 200, (uint8_t *)"2. Phan cung STM32F469NIH6 (Cortex-M4F 180MHz):", LEFT_MODE);
    BSP_LCD_SetTextColor(LCD_COLOR_CYAN);
    BSP_LCD_DisplayStringAt(80, 230, (uint8_t *)"- Man hinh DSI 800x480 IC OTM8009A (2 data lanes)", LEFT_MODE);
    BSP_LCD_DisplayStringAt(80, 255, (uint8_t *)"- Bo nho mo rong SDRAM FMC 16 MBytes (FrameBuffer)", LEFT_MODE);
    BSP_LCD_DisplayStringAt(80, 280, (uint8_t *)"- Co che chong loi DSI_IO_WriteCmd tu phien DEV-279", LEFT_MODE);

    BSP_LCD_SetTextColor(LCD_COLOR_WHITE);
    BSP_LCD_DisplayStringAt(50, 320, (uint8_t *)"3. Hien phap tac tu PRS-16 v3:", LEFT_MODE);
    BSP_LCD_SetTextColor(LCD_COLOR_CYAN);
    BSP_LCD_DisplayStringAt(80, 350, (uint8_t *)"- Datasheet la nguon su that, 4 tang tin cay", LEFT_MODE);

    /* Nut quay lai */
    BSP_LCD_SetTextColor(LCD_COLOR_RED);
    BSP_LCD_FillRect(160, 400, 480, 50);
    BSP_LCD_SetBackColor(LCD_COLOR_RED);
    BSP_LCD_SetTextColor(LCD_COLOR_WHITE);
    BSP_LCD_SetFont(&Font16);
    BSP_LCD_DisplayStringAt(0, 417, (uint8_t *)"[ AN NUT USER BUTTON (PA0) DE DONG ]", CENTER_MODE);
}

void UI_ToggleScreen(void)
{
    if (current_screen == UI_SCREEN_MAIN) {
        UI_ShowDetailsScreen();
    } else {
        UI_ShowMainScreen();
    }
}

ui_screen_t UI_GetCurrentScreen(void)
{
    return current_screen;
}

